sn_aia_tool.script:
(function execute(inputs, outputs) {

    if (!inputs.number) {
        gs.error("❌ Missing input: number");
        return;
    }

    var caseGR = new GlideRecord('x_vuram_financia_0_fcc_kyc_cases');
    if (caseGR.get('number', inputs.number)) {

        // Step 1: deactivate case
        caseGR.setValue('active', false);
        caseGR.update();

        // Step 2: deactivate related Individual/Entity
        var customerType = caseGR.getValue('customer_type'); // 'individual' or 'entity'
        var individualId = caseGR.getValue('individual');
        var entityId     = caseGR.getValue('entity');

        if (customerType == 'individual' && individualId) {
            var indGR = new GlideRecord('x_vuram_financia_0_fcc_kyc_individual_details');
            if (indGR.get(individualId)) {
                indGR.setValue('active', false);
                indGR.update();
            }
        } else if (customerType == 'entity' && entityId) {
            var entGR = new GlideRecord('x_vuram_financia_0_fcc_kyc_entity_details');
            if (entGR.get(entityId)) {
                entGR.setValue('active', false);
                entGR.update();
            }
        }

        // Step 3: deactivate tasks
        var taskGR = new GlideRecord('x_vuram_financia_0_fcc_kyc_tasks');
        taskGR.addQuery('kyc_case', caseGR.getUniqueValue());
        taskGR.query();
        while (taskGR.next()) {
            taskGR.setValue('active', false);
            taskGR.update();
        }

        gs.info("✅ Offboarding completed for Case: " + caseGR.getValue('number'));
    } else {
        gs.error("❌ FCC KYC Case not found for number: " + inputs.number);
    }
})(inputs, outputs);
